#include <iostream>
#include <memory>
struct Resource {int& active;explicit Resource(int& n):active(n){++active;}Resource(const Resource&)=delete;Resource& operator=(const Resource&)=delete;~Resource(){--active;}};
void work(int& active){auto owner=std::make_unique<Resource>(active);std::cout<<active<<' ';return;}
int main(){int active=0;work(active);std::cout<<active<<'\n';}

